37	/// bridge's own processes (a panel member re-exec, the detached background) keep them.
38	pub fn scrub_host_markers(cmd: &mut std::process::Command) {
39	    for (k, _) in std::env::vars_os() {
40	        if let Some(name) = k.to_str() {
41	            if c3_core::host::is_host_marker(name) || c3_core::test_hooks::is_test_var(name) {
