51	/// `CODEX_CONSULT_TEST_HIDE_FAIL=<name>` (test mode only): when it names a host marker present in
52	/// this process's environment, the start is refused. Returns the message body
53	/// `host markers could not be hidden (<name>: <why>)`, or `None` when nothing forces a failure.
54	pub fn host_marker_hide_failure() -> Option<String> {
55	    let fail_on = c3_core::test_hooks::hook("CODEX_CONSULT_TEST_HIDE_FAIL")?;
56	    let fail_on = fail_on.trim();
