pub struct CodexEngine {
    pub launcher: String,
    pub cwd: PathBuf,
    /// The primary turn's streams.
    pub primary: TurnFiles,
    /// The secondary turn's streams (format repair / timeout continuation), when one runs.
    pub secondary: TurnFiles,
    /// (wave 26b, D12) The stall cut in seconds for the PRIMARY turn (`0` = off).
    pub stall_sec: i64,
    /// (wave 26b, D10) The operator's kick file for the PRIMARY turn (`None` = no kick watch).
    pub kick_path: Option<PathBuf>,
    /// Called once per turn, right after the child spawns and before it is waited on, with the
    /// child pid and its start time — the orchestrator flips the recovery record `launching`
    /// -> `running` (`codex-consult.ps1:3330`). `None` leaves the record `launching`.
    pub on_running: Option<std::sync::Arc<dyn Fn(u32, String) + Send + Sync>>,
    /// (wave 3e, F30-2) Told around every tree kill of a turn (`SpawnRequest::on_kill`): the
    /// orchestrator writes the recovery record that names the tree BEFORE the kill. `None`: nothing.
    pub on_kill: Option<super::subprocess::KillHook>,
    /// (wave 8 = plugin wave 30, T15) The quota budget watch of the PRIMARY turn (`None` = off).
    pub budget: Option<super::subprocess::BudgetWatch>,
}

/// (wave 26c, D3 / 28b, D12) One codex `--json` line's effect on the tool calls in flight
/// (`Update-ToolFlight`): a `command_execution` / `mcp_tool_call` / `web_search` item that STARTS
/// opens a call (key `codex:<id>`, label `codex <type> <id>`), one that COMPLETES closes it (by its
/// id, else the first open call of its type). Used to suspend the stall timer while a tool call runs
/// and to name the open call at a stall cut.
pub fn codex_tool_flight(line: &str) -> ToolFlight {
    let v: serde_json::Value = match serde_json::from_str(line) {
        Ok(v) => v,
        Err(_) => return ToolFlight::None,
    };
